// MPL-2.0. Execute pinned Gecko modules with native/DB/network stubs.
// The real tracked overlay is generated by the production source helper.
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile, mkdtemp, rm } from 'node:fs/promises';
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import { createHash, webcrypto } from 'node:crypto';
import { fileURLToPath } from 'node:url';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import vm from 'node:vm';

const execute = promisify(execFile);
// npm test also runs this suite on Node releases that gate SourceTextModule.
if (typeof vm.SourceTextModule !== 'function') {
  test('full pinned Remote Settings VM regression suite', async () => {
    const environment = { ...process.env };
    delete environment.NODE_TEST_CONTEXT;
    const result = await execute(process.execPath, ['--experimental-vm-modules', '--test',
      '--test-reporter=tap', fileURLToPath(import.meta.url)], {
      env: environment, timeout: 30000, maxBuffer: 1024 * 1024,
    });
    assert.match(result.stdout, /# pass 8\b/);
    assert.match(result.stdout, /# fail 0\b/);
  });
} else {
const root = fileURLToPath(new URL('../', import.meta.url));
const reference = join(root, 'tests/fixtures/android-remote-settings');
const digest = bytes => createHash('sha256').update(bytes).digest('hex');
const manifest = JSON.parse(await readFile(join(reference, 'provenance.json'), 'utf8'));
const lock = JSON.parse(await readFile(join(root, 'android/engine-lock.json'), 'utf8'));
assert.equal(lock.sourceRevision, manifest.sourceRevision);
assert.equal(lock.artifact, manifest.artifact);
assert.equal(lock.aar.sha256, manifest.aarSHA256);
assert.equal(lock.integration.id, 'cyphra-app-uri-no-interrupt-v3');
const dumpBytes = await readFile(join(reference, manifest.onecrl.fixtureFile));
assert.equal(digest(dumpBytes), manifest.onecrl.fixtureSHA256);
const dump = JSON.parse(dumpBytes);
assert.equal(dump.timestamp, manifest.onecrl.timestamp);
assert.equal(dump.data.length, 6);
const advisoryRecords = dump.data.filter(record => record.enabled
  && record.details?.bug === 'https://bugzilla.mozilla.org/show_bug.cgi?id=2083382');
assert.equal(advisoryRecords.length, 6);
assert.deepEqual(advisoryRecords.map(record => record.id), manifest.onecrl.selectedRecords.map(record => record.id));
// Hash each real record recursively, independently of fixture pretty printing.
const canonical = value => Array.isArray(value) ? value.map(canonical)
  : value && typeof value === 'object' ? Object.fromEntries(Object.keys(value).sort()
    .map(key => [key, canonical(value[key])])) : value;
for (const [index, record] of advisoryRecords.entries()) {
  assert.equal(digest(JSON.stringify(canonical(record))), manifest.onecrl.selectedRecords[index].canonicalJSONSHA256);
}
const sourceNames = ['Utils.sys.mjs', 'SharedUtils.sys.mjs', 'Attachments.sys.mjs',
  'RemoteSettingsClient.sys.mjs', 'remote-settings.sys.mjs', 'RemoteSecuritySettings.sys.mjs'];
const original = new Map(await Promise.all(sourceNames.map(async name => {
  const bytes = await readFile(join(reference, name));
  assert.equal(bytes.length, manifest.modules[name].bytes);
  assert.equal(digest(bytes), manifest.modules[name].sha256, `Pinned upstream module ${name}`);
  return [name, bytes.toString('utf8')];
})));
const utilsPin = lock.integration.modules.find(module => module.archivePath === 'modules/services-settings/Utils.sys.mjs');
assert.ok(utilsPin);
assert.equal(utilsPin.upstreamSha256, manifest.modules['Utils.sys.mjs'].sha256);
assert.equal(await readFile(join(root, utilsPin.upstreamSource), 'utf8'), original.get('Utils.sys.mjs'));
const generated = await mkdtemp(join(tmpdir(), 'cyphra-remote-settings-source-'));
let guarded;
try {
  const result = await execute('python3', [join(root, 'scripts/patch-android-engine.py'),
    'source', '--output', generated], { cwd: root, timeout: 10000 });
  assert.equal(JSON.parse(result.stdout).modifiedModules, 3);
  guarded = await readFile(join(generated, 'Utils.sys.mjs'), 'utf8');
  assert.equal(digest(guarded), utilsPin.patchedSha256);
} finally {
  await rm(generated, { recursive: true, force: true });
}
const moduleURI = name => `resource://services-settings/${name}`;

async function harness({ patched = true, databaseFailure = false, preexistingTimestamp = null } = {}) {
  const network = { constructors: 0, opens: 0, sends: 0, globalNetworkAttempts: 0,
    verifierCalls: 0, kintoExecutions: 0, nativeStates: [], resourceRequests: [], localUptake: [], imports: [] };
  const databases = new Map();
  const prefs = new Map([['services.settings.server', 'data:,']]);
  const log = { debug() {}, info() {}, warn() {}, error() {} };
  const modules = new Map();
  const known = new Map();
  const notifications = [];
  const completion = new Map();
  const fetchResource = async input => {
    const uri = String(input);
    if (!uri.startsWith('resource://')) {
      network.globalNetworkAttempts++;
      throw new Error(`Unexpected live fetch in offline harness: ${uri}`);
    }
    network.resourceRequests.push(uri);
    if (uri === 'resource://app/defaults/settings/security-state/onecrl.json') {
      return new Response(dumpBytes, { status: 200 });
    }
    if (uri === 'resource://app/defaults/settings/last_modified.json') {
      return Response.json({ 'security-state/onecrl': dump.timestamp });
    }
    if (uri === 'resource://app/defaults/settings/security-state/onecrl/local.meta.json') {
      return Response.json({ id: 'local', attachment: { size: 3, hash: 'stub-verified' } });
    }
    if (uri === 'resource://app/defaults/settings/security-state/onecrl/local') {
      return new Response(new Uint8Array([1, 2, 3]));
    }
    throw new Error(`No packaged fixture at ${uri}`);
  };
  const lazyGetter = (target, name, getter) => Object.defineProperty(target, name, {
    configurable: true, enumerable: true,
    get() { const value = getter(); Object.defineProperty(target, name,
      { value, configurable: true, enumerable: true, writable: true }); return value; },
  });
  const getExport = (uri, name) => {
    const exports = modules.has(uri) ? modules.get(uri).namespace : known.get(uri);
    if (!exports || !(name in exports)) throw new Error(`Unstubbed Gecko import ${uri}#${name}`);
    return exports[name];
  };
  const preference = (name, fallback) => prefs.has(name) ? prefs.get(name) : fallback;
  const branch = prefix => ({
    getStringPref: (name, fallback) => preference(prefix + name, fallback),
    getBoolPref: (name, fallback) => preference(prefix + name, fallback),
    getIntPref: (name, fallback) => preference(prefix + name, fallback),
    prefHasUserValue: name => prefs.has(prefix + name),
    clearUserPref: name => prefs.delete(prefix + name),
    addObserver() {},
  });
  class EmptyDatabaseError extends Error {}
  class Database {
    static EmptyDatabaseError = EmptyDatabaseError;
    constructor(identifier) { this.identifier = identifier; }
    async getLastModified() {
      if (databaseFailure) throw new Error('Simulated unreadable IndexedDB');
      return databases.get(this.identifier)?.timestamp ?? preexistingTimestamp;
    }
    async list() {
      const state = databases.get(this.identifier);
      if (!state) throw new EmptyDatabaseError('No imported local data');
      return structuredClone(state.data);
    }
    async getMetadata() { return {}; }
  }
  class ServiceRequest {
    constructor() { network.constructors++; }
    open() { network.opens++; }
    send() { network.sends++; this.response = new ArrayBuffer(0); this.status = 200;
      this.statusText = 'OK'; this.responseURL = 'https://example.invalid/'; this.onload(); }
    getAllResponseHeaders() { return 'Content-Type: application/json'; }
    setRequestHeader() {}
  }
  const storage = {
    hasPriorData(type, callback) { callback(0, false); },
    setRevocations(states, callback) { network.nativeStates.push(...states); callback(0); },
  };
  const Services = {
    env: { get: () => '', exists: () => false },
    prefs: { ...branch(''), getBranch: prefix => branch(prefix) },
    policies: { isAllowed: () => true }, startup: { shuttingDown: false },
    appinfo: { processType: 0, PROCESS_TYPE_DEFAULT: 0, OS: 'Android' }, io: { offline: false },
    obs: { addObserver() {}, notifyObservers(subject, topic) {
      notifications.push(topic); completion.get(topic)?.();
    } },
  };
  const XPCOMUtils = {
    defineLazyPreferenceGetter(target, name, pref, fallback) {
      Object.defineProperty(target, name, { configurable: true, get: () => preference(pref, fallback) });
    },
    defineLazyServiceGetter(target, name) {
      target[name] = name === 'gNetworkLinkService' ? { isLinkUp: true } : { state: 0, LOCKED_PORTAL: 1 };
    },
    declareLazy(entries) { const target = {}; for (const [name, getter] of Object.entries(entries))
      lazyGetter(target, name, getter); return target; },
  };
  const ChromeUtils = {
    defineLazyGetter: lazyGetter,
    defineESModuleGetters(target, entries) { for (const [name, uri] of Object.entries(entries))
      lazyGetter(target, name, () => getExport(uri, name)); },
    importESModule(uri) {
      assert.equal(uri, 'resource://gre/modules/Console.sys.mjs');
      return { ConsoleAPI: class { constructor() { return log; } } };
    },
    generateQI: () => function () {}, now: () => 0, addProfilerMarker() {},
  };
  const context = vm.createContext({ Services, ChromeUtils,
    Ci: { nsICaptivePortalService: {}, nsINetworkLinkService: {},
      nsICertStorage: { STATE_ENFORCE: 1, STATE_UNSET: 0, DATA_TYPE_REVOCATION: 1,
        DATA_TYPE_CERTIFICATE: 2, TRUST_INHERIT: 0 },
      nsIContentSignatureVerifier: { ContentSignatureProdRoot: 1, ContentSignatureLocalRoot: 2,
        ContentSignatureStageRoot: 3, ContentSignatureDevRoot: 4 } },
    Cr: { NS_OK: 0 }, Cu: { isInAutomation: false },
    Cc: { '@mozilla.org/security/certstorage;1': { getService: () => storage },
      '@mozilla.org/security/contentsignatureverifier;1': { createInstance: () => ({
        async asyncVerifyContentSignature() { network.verifierCalls++; return true; },
      }) } },
    crypto: webcrypto, fetch: fetchResource, Response, Headers, TextDecoder, TextEncoder,
    DOMException, console: log, URL, structuredClone,
  });
  known.set('resource://gre/modules/AppConstants.sys.mjs', { AppConstants: {
    RELEASE_OR_BETA: true, REMOTE_SETTINGS_DEFAULT_BUCKET: 'main', REMOTE_SETTINGS_VERIFY_SIGNATURE: true,
    REMOTE_SETTINGS_SERVER_URLS: ['https://firefox.settings.services.mozilla.com/v1'],
  } });
  known.set('resource://gre/modules/ServiceRequest.sys.mjs', { ServiceRequest });
  known.set('resource://gre/modules/XPCOMUtils.sys.mjs', { XPCOMUtils });
  known.set('resource://gre/modules/Timer.sys.mjs', { setTimeout() { throw new Error('Unexpected timer'); } });
  known.set('resource://gre/modules/psm/X509.sys.mjs', { X509: {} });
  known.set('resource://gre/modules/components-utils/ClientEnvironment.sys.mjs', { ClientEnvironmentBase: {} });
  known.set('resource://gre/modules/ObjectUtils.sys.mjs', { ObjectUtils: { isEmpty: value => Object.keys(value).length === 0 } });
  known.set('resource://services-settings/Database.sys.mjs', { Database });
  known.set('resource://services-settings/IDBHelpers.sys.mjs', { IDBHelpers: {
    IndexedDBError: class extends Error {}, ShutdownError: class extends Error {},
  } });
  known.set('resource://services-settings/UptakeTelemetry.sys.mjs', { UptakeTelemetry: {
    STATUS: new Proxy({}, { get: (_, name) => String(name) }),
    async report(status, args) { network.localUptake.push({ status, args }); },
  } });
  known.set('resource://services-common/kinto-http-client.sys.mjs', { KintoHttpClient: class {
    constructor(server, { fetchFunc }) { this.server = server; this.fetchFunc = fetchFunc; }
    bucket() { return this; } collection() { return this; }
    async execute({ path }) { network.kintoExecutions++; return this.fetchFunc(this.server + path); }
  } });
  known.set('resource://services-settings/RemoteSettingsWorker.sys.mjs', { RemoteSettingsWorker: {
    async importJSONDump(bucket, collection) {
      network.imports.push(`${bucket}/${collection}`);
      const value = await getExport(moduleURI('SharedUtils.sys.mjs'), 'SharedUtils').loadJSONDump(bucket, collection);
      if (!value.data) return -1;
      databases.set(`${bucket}/${collection}`, structuredClone(value));
      return value.data.length;
    },
    async canonicalStringify() { return '{}'; },
  } });
  for (const name of sourceNames) {
    const uri = name === 'RemoteSecuritySettings.sys.mjs'
      ? 'resource://gre/modules/psm/RemoteSecuritySettings.sys.mjs' : moduleURI(name);
    modules.set(uri, new vm.SourceTextModule(name === 'Utils.sys.mjs' && patched ? guarded : original.get(name),
      { context, identifier: uri, initializeImportMeta(meta) { meta.url = uri; } }));
  }
  const synthetic = new Map();
  const link = uri => {
    if (modules.has(uri)) return modules.get(uri);
    if (!known.has(uri)) throw new Error(`Unexpected static import ${uri}`);
    if (!synthetic.has(uri)) {
      const exports = known.get(uri);
      synthetic.set(uri, new vm.SyntheticModule(Object.keys(exports), function () {
        for (const [name, value] of Object.entries(exports)) this.setExport(name, value);
      }, { context, identifier: uri }));
    }
    return synthetic.get(uri);
  };
  for (const module of modules.values()) if (module.status === 'unlinked') await module.link(link);
  for (const module of modules.values()) if (module.status === 'linked') await module.evaluate();
  return { network, prefs, notifications, completion,
    Utils: getExport(moduleURI('Utils.sys.mjs'), 'Utils'),
    RemoteSettings: getExport(moduleURI('remote-settings.sys.mjs'), 'RemoteSettings'),
    RemoteSecuritySettings: getExport('resource://gre/modules/psm/RemoteSecuritySettings.sys.mjs', 'RemoteSecuritySettings'),
    Downloader: getExport(moduleURI('Attachments.sys.mjs'), 'Downloader'),
  };
}

function noNetwork(value) {
  assert.equal(value.network.constructors, 0, 'No ServiceRequest constructor');
  assert.equal(value.network.opens, 0); assert.equal(value.network.sends, 0);
  assert.equal(value.network.globalNetworkAttempts, 0);
}
async function startBundle(value) {
  const ready = new Promise(resolve => value.completion.set('remote-security-settings:onecrl-bundle-loaded', resolve));
  value.RemoteSecuritySettings.init(); await ready;
}

// Positive control proves the stubs would observe a live request on the pinned upstream code.
test('upstream Release/Beta ignores data override and reaches ServiceRequest; guarded module preserves dump eligibility', async () => {
  const before = await harness({ patched: false });
  assert.equal(before.Utils.SERVER_URL, 'https://firefox.settings.services.mozilla.com/v1');
  assert.equal(before.Utils.LOAD_DUMPS, true);
  assert.equal(before.Utils.shouldSkipRemoteActivity, false);
  await before.Utils.fetch('https://example.invalid/control');
  assert.equal(before.network.constructors, 1); assert.equal(before.network.sends, 1);
  const after = await harness();
  assert.equal(after.Utils.SERVER_URL, before.Utils.SERVER_URL);
  assert.equal(after.Utils.LOAD_DUMPS, true);
  assert.equal(after.Utils.shouldSkipRemoteActivity, true);
  assert.equal(after.Utils.CERT_CHAIN_ROOT_IDENTIFIER, before.Utils.CERT_CHAIN_ROOT_IDENTIFIER);
  noNetwork(after);
});

test('actual startup init/get/import/dump/update installs all six authentic AAR advisory identities without a request', async () => {
  const value = await harness(); await startBundle(value);
  assert.deepEqual(value.network.imports, ['security-state/onecrl']);
  assert.ok(value.network.resourceRequests.includes('resource://app/defaults/settings/security-state/onecrl.json'));
  assert.equal(value.network.nativeStates.length, dump.data.length);
  for (const record of advisoryRecords) {
    assert.ok(value.network.nativeStates.some(state => state.issuer === record.issuerName
      && state.serial === record.serialNumber && state.state === 1), record.id);
  }
  assert.equal(value.network.localUptake.length, 0);
  value.RemoteSecuritySettings.init();
  assert.equal(value.notifications.filter(topic => topic === 'remote-security-settings:onecrl-bundle-loaded').length, 1);
  noNetwork(value);
});

test('actual get dump fallback still installs advisory revocations when local database is unreadable', async () => {
  const value = await harness({ databaseFailure: true }); await startBundle(value);
  for (const record of advisoryRecords) assert.ok(value.network.nativeStates.some(state =>
    state.issuer === record.issuerName && state.serial === record.serialNumber && state.state === 1));
  assert.ok(value.network.resourceRequests.includes('resource://app/defaults/settings/security-state/onecrl.json'));
  noNetwork(value);
});

test('actual get refreshes an older local DB from the packaged dump with network disabled', async () => {
  const value = await harness({ preexistingTimestamp: 1 }); await startBundle(value);
  assert.deepEqual(value.network.imports, ['security-state/onecrl']);
  assert.equal(value.network.nativeStates.length, dump.data.length);
  noNetwork(value);
});

test('actual scheduled poll/startup bundle/client sync return before network or local uptake', async () => {
  const value = await harness();
  await value.RemoteSettings.pollChanges({ trigger: 'timer' });
  assert.equal((await value.RemoteSettings.pullStartupBundle()).length, 0);
  await value.RemoteSettings('onecrl', { bucketName: 'security-state' }).sync();
  assert.equal(value.network.localUptake.length, 0);
  noNetwork(value);
});

test('central fetch denies direct calls and proxy-bypass options before request construction', async () => {
  const value = await harness();
  for (const uri of ['https://firefox.settings.services.mozilla.com/v1/',
    'https://firefox-settings-attachments.cdn.mozilla.net/file', 'http://127.0.0.1:1/']) {
    for (const bypassProxy of [false, true]) await assert.rejects(value.Utils.fetch(uri, { bypassProxy }),
      /Cyphra disables Remote Settings network activity/);
  }
  noNetwork(value);
});

test('actual direct maybeSync cannot bypass fetch guard; inherited local uptake is explicit', async () => {
  const value = await harness(); await startBundle(value);
  const client = value.RemoteSecuritySettings.OneCRLBlocklistClient;
  await assert.rejects(client.maybeSync(dump.timestamp, { loadDump: false }), /Cyphra disables Remote Settings network activity/);
  assert.equal(value.network.kintoExecutions, 1, 'Actual maybeSync reached the HTTP adapter');
  assert.ok(value.network.localUptake.some(item => item.status === 'SYNC_START'));
  assert.equal(client._syncRunning, false);
  noNetwork(value);
});

test('actual attachment and signature-chain paths fail before network; local attachment reads survive', async () => {
  const value = await harness();
  const downloader = new value.Downloader('security-state', 'onecrl');
  await assert.rejects(downloader._fetchAttachment('https://firefox-settings-attachments.cdn.mozilla.net/file'),
    /Cyphra disables Remote Settings network activity/);
  const client = value.RemoteSettings('onecrl', { bucketName: 'security-state', signerName: 'onecrl.content-signature.mozilla.org' });
  await assert.rejects(client.validateCollectionSignature([], dump.timestamp, { signatures: [{
    x5u: 'https://content-signature-2.cdn.mozilla.net/g/chains/202402/onecrl.content-signature.mozilla.org-example.chain',
    mode: 'p384ecdsa', signature: 'not-used-network-is-denied',
  }] }), /Cyphra disables Remote Settings network activity/);
  assert.equal(value.network.verifierCalls, 0);
  const local = await downloader._readAttachmentDump('local');
  assert.deepEqual(Array.from(new Uint8Array(await local.readBuffer())), [1, 2, 3]);
  noNetwork(value);
});

}
